// T-AGENT: the identity files (docs/prd/targets-connect.md §10.3, FR13): generated by the agent, persisted atomically as 0600 in a 0700 folder, loaded with
// every field checked, and consistent with the contract's test vector; a damaged file is an error, never an empty identity.
import assert from 'node:assert/strict';
import { chmodSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { after, before, describe, it } from 'node:test';
import { CONNECT_TEST_VECTORS } from '@portal/contracts';
import { generateNodeKeyPair, keyPairFromSeed, fromB64u } from '../tunnel/auth.js';
import { FileIdentityStore, IdentityError, fingerprintOf, identityText, parseIdentity, writeFileAtomic, type Identity } from './identity.js';

let dir: string;
before(() => void (dir = mkdtempSync(join(tmpdir(), 'cx2-id-'))));
after(() => rmSync(dir, { recursive: true, force: true }));

const make = (over: Partial<Identity> = {}): Identity => {
  const k = generateNodeKeyPair();
  return { node: 'nd_0123456789ab', target: 'lab', portalUrl: 'https://pilot.example.com', portalId: null, privateKey: k.privateKey, publicKey: k.publicKey, enrolledAt: '2026-10-12T09:00:00.000Z', ...over };
};

describe('identity', () => {
  it('the fingerprint is the contract’s: the first 32 hex of SHA-256 over the raw public key', () => {
    const k = keyPairFromSeed(fromB64u(CONNECT_TEST_VECTORS.handshake.seed));
    assert.equal(k.publicKey, CONNECT_TEST_VECTORS.handshake.publicKey);
    assert.equal(fingerprintOf({ publicKey: k.publicKey }), CONNECT_TEST_VECTORS.handshake.fingerprint);
  });

  it('writes 0600 in a 0700 folder, atomically (no temporary file is left), and loads what it wrote', async () => {
    const store = new FileIdentityStore(join(dir, 'a', 'b'));
    assert.equal(await store.load(), null);
    const id = make();
    await store.save(id);
    assert.deepEqual(await store.load(), id);
    assert.equal(statSync(join(dir, 'a', 'b', 'identity.json')).mode & 0o777, 0o600);
    assert.equal(statSync(join(dir, 'a', 'b')).mode & 0o777, 0o700);
    assert.deepEqual(readdirSync(join(dir, 'a', 'b')), ['identity.json']);
    const pinned = { ...id, portalId: 'portal-1' };
    await store.save(pinned);
    assert.equal((await store.load())!.portalId, 'portal-1');
    assert.equal(await store.mode(), 0o600);
  });

  it('keeps a rotation’s next identity beside the current one: save, load, promote, drop', async () => {
    const store = new FileIdentityStore(join(dir, 'rot'));
    const cur = make();
    await store.save(cur);
    const n = (() => {
      const k = generateNodeKeyPair();
      return { ...cur, privateKey: k.privateKey, publicKey: k.publicKey };
    })();
    await store.saveNext(n);
    assert.deepEqual(await store.loadNext(), n);
    assert.deepEqual(await store.load(), cur);
    assert.deepEqual(await store.promoteNext(), n);
    assert.deepEqual(await store.load(), n);
    assert.equal(await store.loadNext(), null);
    assert.equal(await store.promoteNext(), null);
    await store.saveNext(cur);
    await store.dropNext();
    assert.equal(await store.loadNext(), null);
    // A damaged next is a rotation abandoned, not an error.
    writeFileSync(join(dir, 'rot', 'identity.next.json'), '{oops');
    assert.equal(await store.loadNext(), null);
  });

  it('a damaged or inconsistent file is an IdentityError that never echoes the key', () => {
    const id = make();
    assert.throws(() => parseIdentity('{nope'), IdentityError);
    assert.throws(() => parseIdentity(JSON.stringify({ ...id, node: '' })), /missing a field/);
    const other = generateNodeKeyPair();
    try {
      parseIdentity(JSON.stringify({ ...id, publicKey: other.publicKey }));
      assert.fail('a public key that is not the private key’s must be refused');
    } catch (e) {
      assert.ok(e instanceof IdentityError);
      assert.equal(String((e as Error).message).includes(id.privateKey), false);
    }
    assert.throws(() => parseIdentity(JSON.stringify({ ...id, privateKey: 'AAAA' })), IdentityError);
    assert.equal(parseIdentity(identityText(id)).portalId, null);
  });

  it('writeFileAtomic replaces a file whole, and leaves no temporary file when it fails', { skip: process.getuid?.() === 0 ? 'root can write into a read-only folder' : false }, async () => {
    const f = join(dir, 'atomic.txt');
    await writeFileAtomic(f, 'one', 0o600);
    await writeFileAtomic(f, 'two', 0o600);
    assert.equal(readFileSync(f, 'utf8'), 'two');
    chmodSync(dir, 0o500);
    try {
      await assert.rejects(writeFileAtomic(join(dir, 'denied.txt'), 'x'));
    } finally {
      chmodSync(dir, 0o700);
    }
    assert.ok(!readdirSync(dir).some((n) => n.endsWith('.tmp')));
  });
});
